INSERT INTO `t_ai_chat_message` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `del_flag`, `session_id`, `role`, `content`) VALUES (61, '1', '2025-09-09 14:54:52', '1', '2025-09-09 14:54:52', 0, 5, 'assistant', '我理解您可能在表达某种情绪，但这种言论是不恰当且伤人的。如果您正感到不满或有其他情感需要倾诉，我希望我们可以用一种更加积极和尊重的方式沟通。如果有任何问题或需要帮助，请告诉我，我很愿意提供支持。');
