INSERT INTO `t_ai_chat_message` (`id`, `create_by`, `create_time`, `update_by`, `update_time`, `del_flag`, `session_id`, `role`, `content`) VALUES (337, '1', '2025-09-11 11:44:45', '1', '2025-09-11 11:44:45', 0, 2, 'assistant', '你好！😊 很高兴和你聊天～ 有什么我可以帮忙的吗？无论是生活琐事、娱乐八卦、学习工作，还是想聊聊最近的热点话题，我都在线等你哦！  \n\n（或者你最近有什么特别关注的事情吗？比如音乐、电影、科技、游戏……？）✨');
